/// `DC_EVErrorCodeType`.
///
/// 12 values, so 4 bits. Discriminants are the EXI indices, which
/// follow schema document order rather than sort order.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash, PartialOrd, Ord)]
#[cfg_attr(feature = "serde", derive(serde::Serialize, serde::Deserialize))]
#[repr(u16)]
pub enum DCEVErrorCode {
    /// `NO_ERROR`
    NOERROR = 0,
    /// `FAILED_RESSTemperatureInhibit`
    FAILEDRESSTemperatureInhibit = 1,
    /// `FAILED_EVShiftPosition`
    FAILEDEVShiftPosition = 2,
    /// `FAILED_ChargerConnectorLockFault`
    FAILEDChargerConnectorLockFault = 3,
    /// `FAILED_EVRESSMalfunction`
    FAILEDEVRESSMalfunction = 4,
    /// `FAILED_ChargingCurrentdifferential`
    FAILEDChargingCurrentdifferential = 5,
    /// `FAILED_ChargingVoltageOutOfRange`
    FAILEDChargingVoltageOutOfRange = 6,
    /// `Reserved_A`
    ReservedA = 7,
    /// `Reserved_B`
    ReservedB = 8,
    /// `Reserved_C`
    ReservedC = 9,
    /// `FAILED_ChargingSystemIncompatibility`
    FAILEDChargingSystemIncompatibility = 10,
    /// `NoData`
    NoData = 11,
}

impl DCEVErrorCode {
    /// Event-code width of this enumeration.
    pub const WIDTH: u32 = 4;

    /// Every value, in EXI index order.
    pub const ALL: [Self; 12] = [
        Self::NOERROR,
        Self::FAILEDRESSTemperatureInhibit,
        Self::FAILEDEVShiftPosition,
        Self::FAILEDChargerConnectorLockFault,
        Self::FAILEDEVRESSMalfunction,
        Self::FAILEDChargingCurrentdifferential,
        Self::FAILEDChargingVoltageOutOfRange,
        Self::ReservedA,
        Self::ReservedB,
        Self::ReservedC,
        Self::FAILEDChargingSystemIncompatibility,
        Self::NoData,
    ];

    /// The EXI index of this value.
    #[must_use]
    pub const fn as_index(self) -> u64 {
        self as u64
    }

    /// Parses an EXI index.
    pub const fn from_index(index: u64) -> ExiResult<Self> {
        Ok(match index {
            0 => Self::NOERROR,
            1 => Self::FAILEDRESSTemperatureInhibit,
            2 => Self::FAILEDEVShiftPosition,
            3 => Self::FAILEDChargerConnectorLockFault,
            4 => Self::FAILEDEVRESSMalfunction,
            5 => Self::FAILEDChargingCurrentdifferential,
            6 => Self::FAILEDChargingVoltageOutOfRange,
            7 => Self::ReservedA,
            8 => Self::ReservedB,
            9 => Self::ReservedC,
            10 => Self::FAILEDChargingSystemIncompatibility,
            11 => Self::NoData,
            _ => return Err(ExiError::UnknownEnumValue),
        })
    }

    /// The lexical form this value has in the schema.
    #[must_use]
    pub const fn as_str(self) -> &'static str {
        match self {
            Self::NOERROR => "NO_ERROR",
            Self::FAILEDRESSTemperatureInhibit => "FAILED_RESSTemperatureInhibit",
            Self::FAILEDEVShiftPosition => "FAILED_EVShiftPosition",
            Self::FAILEDChargerConnectorLockFault => "FAILED_ChargerConnectorLockFault",
            Self::FAILEDEVRESSMalfunction => "FAILED_EVRESSMalfunction",
            Self::FAILEDChargingCurrentdifferential => "FAILED_ChargingCurrentdifferential",
            Self::FAILEDChargingVoltageOutOfRange => "FAILED_ChargingVoltageOutOfRange",
            Self::ReservedA => "Reserved_A",
            Self::ReservedB => "Reserved_B",
            Self::ReservedC => "Reserved_C",
            Self::FAILEDChargingSystemIncompatibility => "FAILED_ChargingSystemIncompatibility",
            Self::NoData => "NoData",
        }
    }
}

