/// `DC_EVSEStatusCodeType`.
///
/// 12 values, so 4 bits. Discriminants are the EXI indices, which
/// follow schema document order rather than sort order.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash, PartialOrd, Ord)]
#[cfg_attr(feature = "serde", derive(serde::Serialize, serde::Deserialize))]
#[repr(u16)]
pub enum DCEVSEStatusCode {
    /// `EVSE_NotReady`
    EVSENotReady = 0,
    /// `EVSE_Ready`
    EVSEReady = 1,
    /// `EVSE_Shutdown`
    EVSEShutdown = 2,
    /// `EVSE_UtilityInterruptEvent`
    EVSEUtilityInterruptEvent = 3,
    /// `EVSE_IsolationMonitoringActive`
    EVSEIsolationMonitoringActive = 4,
    /// `EVSE_EmergencyShutdown`
    EVSEEmergencyShutdown = 5,
    /// `EVSE_Malfunction`
    EVSEMalfunction = 6,
    /// `Reserved_8`
    Reserved8 = 7,
    /// `Reserved_9`
    Reserved9 = 8,
    /// `Reserved_A`
    ReservedA = 9,
    /// `Reserved_B`
    ReservedB = 10,
    /// `Reserved_C`
    ReservedC = 11,
}

impl DCEVSEStatusCode {
    /// Event-code width of this enumeration.
    pub const WIDTH: u32 = 4;

    /// Every value, in EXI index order.
    pub const ALL: [Self; 12] = [
        Self::EVSENotReady,
        Self::EVSEReady,
        Self::EVSEShutdown,
        Self::EVSEUtilityInterruptEvent,
        Self::EVSEIsolationMonitoringActive,
        Self::EVSEEmergencyShutdown,
        Self::EVSEMalfunction,
        Self::Reserved8,
        Self::Reserved9,
        Self::ReservedA,
        Self::ReservedB,
        Self::ReservedC,
    ];

    /// The EXI index of this value.
    #[must_use]
    pub const fn as_index(self) -> u64 {
        self as u64
    }

    /// Parses an EXI index.
    pub const fn from_index(index: u64) -> ExiResult<Self> {
        Ok(match index {
            0 => Self::EVSENotReady,
            1 => Self::EVSEReady,
            2 => Self::EVSEShutdown,
            3 => Self::EVSEUtilityInterruptEvent,
            4 => Self::EVSEIsolationMonitoringActive,
            5 => Self::EVSEEmergencyShutdown,
            6 => Self::EVSEMalfunction,
            7 => Self::Reserved8,
            8 => Self::Reserved9,
            9 => Self::ReservedA,
            10 => Self::ReservedB,
            11 => Self::ReservedC,
            _ => return Err(ExiError::UnknownEnumValue),
        })
    }

    /// The lexical form this value has in the schema.
    #[must_use]
    pub const fn as_str(self) -> &'static str {
        match self {
            Self::EVSENotReady => "EVSE_NotReady",
            Self::EVSEReady => "EVSE_Ready",
            Self::EVSEShutdown => "EVSE_Shutdown",
            Self::EVSEUtilityInterruptEvent => "EVSE_UtilityInterruptEvent",
            Self::EVSEIsolationMonitoringActive => "EVSE_IsolationMonitoringActive",
            Self::EVSEEmergencyShutdown => "EVSE_EmergencyShutdown",
            Self::EVSEMalfunction => "EVSE_Malfunction",
            Self::Reserved8 => "Reserved_8",
            Self::Reserved9 => "Reserved_9",
            Self::ReservedA => "Reserved_A",
            Self::ReservedB => "Reserved_B",
            Self::ReservedC => "Reserved_C",
        }
    }
}

